<?php
require_once __DIR__.'/includes/bootstrap.php';$user=require_login();$logs=read_data('telemetry.json',[]);$items=array_values(array_filter($logs,fn($l)=>(int)($l['user_id']??0)===$user['id']));$q=trim($_GET['q']??'');if($q!=='')$items=array_values(array_filter($items,fn($l)=>stripos(($l['title']??'').' '.($l['source']??''),$q)!==false));
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="fairshare-kontribusi.csv"');$o=fopen('php://output','w');fputcsv($o,['Aktivitas','Sumber','Tanggal','Poin','Status']);foreach($items as $i)fputcsv($o,[$i['title'],$i['source'],$i['date'],$i['points'],$i['status']]);fclose($o);exit;}
layout_start('Kontribusi Saya','contributions');page_heading('FAIRSHARE / KONTRIBUSI','Kontribusi Saya','Lihat jejak kontribusi, sumber aktivitas, dan progres yang tercatat.',button('↓ Ekspor CSV','contributions.php?export=csv','secondary'));
echo '<div class="stats-grid three-stats"><article class="stat-card"><div class="stat-label">WEI SCORE</div><div class="stat-number">'.number_format(score_for_user($user['id']),1).'<small>/100</small></div><div class="stat-foot">Skor dari telemetri lokal</div></article><article class="stat-card"><div class="stat-label">TOTAL AKTIVITAS</div><div class="stat-number">'.count($items).'<small> event</small></div><div class="stat-foot">Catatan yang cocok dengan pencarian</div></article><article class="stat-card"><div class="stat-label">SUMBER TERHUBUNG</div><div class="stat-number">'.count(array_unique(array_column($items,'source'))).'<small> sumber</small></div><div class="stat-foot">Sumber data lokal</div></article></div><section class="panel"><div class="panel-heading"><div><div class="panel-title">Riwayat kontribusi</div><div class="panel-sub">Gunakan pencarian untuk menemukan aktivitas</div></div><form class="search-form" method="get"><input name="q" value="'.e($q).'" placeholder="Cari aktivitas atau sumber..."><button class="btn secondary">Cari</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Aktivitas</th><th>Sumber</th><th>Tanggal</th><th>Poin</th><th>Status</th></tr></thead><tbody>';
if(!$items)echo '<tr><td colspan="5"><div class="empty-state"><span class="empty-illustration">◈</span><b>Belum ada telemetri</b><p>Aktivitas GitHub/Google akan muncul setelah integrasi dikonfigurasi atau data dicatat.</p></div></td></tr>';
foreach(array_reverse($items) as $i)echo '<tr><td><div class="table-main"><span class="table-icon">◈</span><b>'.e($i['title']).'</b></div></td><td><span class="source-label">'.e(strtoupper($i['source'])).'</span></td><td>'.e(format_date($i['date'])).'</td><td><b>'.e($i['points']).'</b></td><td><span class="status-badge '.(($i['status']??'')==='Terverifikasi'?'good':'waiting').'">'.e($i['status']).'</span></td></tr>';
echo '</tbody></table></div></section>';layout_end();
